function materialSuggestionsHTML(){
 const groups=MaterialSuggestionsCore.groups(state.lines,CATALOG);if(!groups.length)return '';
 return `<section class="card" id="material-suggestions"><h2>Дополните состав изделия</h2><p class="small">Покрытия и обработка предлагаются по материалам. Выберите применимые позиции; объёмы и нормы требуют проверки. Если комплексная работа уже включает эти операции, не добавляйте их повторно.</p>${groups.map((g,i)=>`<div class="suggestion-group"><h3>${g.type==='wood'?'Дерево: защита и обработка':'Обычная сталь: подготовка и покрытие'} · ${esc(g.group)}</h3><p class="small">${g.scope==='batch'?'Объём на всю партию':'Объём на одно изделие'}${g.type==='steel'?' · Подтвердите схему защиты: цинкование и порошок применяются по условиям заказа.':''}</p>${g.rules.map((rule,j)=>{const options=MaterialSuggestionsCore.options(rule,CATALOG),present=options.some(c=>MaterialSuggestionsCore.exists(state.lines,c,g.group,g.scope));return `<div class="suggestion-row"><div class="field"><label for="suggest-${i}-${j}">${esc(rule.label)}${present?' · уже есть вариант в группе':''}</label><select id="suggest-${i}-${j}">${options.map(c=>`<option value="${esc(c.id)}">${esc(c.name)} · ${money(c.price)} / ${esc(MaterialCore.unitLabel(c.unit))}${MaterialSuggestionsCore.exists(state.lines,c,g.group,g.scope)?' · добавлено':''}</option>`).join('')}</select></div><button type="button" onclick="addMaterialSuggestion(${i},${j})" ${!options.length?'disabled':''}>Добавить</button></div>`;}).join('')}</div>`).join('')}<p class="small">Для торцовочной пилы отдельной ставки в справочнике нет: цена останется неизвестной до заполнения. Объём покрытия вводится в литрах, работ — в единицах выбранной ставки. Площадь, слои и нормы автоматически не подставляются.</p></section>`;
}
function addMaterialSuggestion(i,j){const g=MaterialSuggestionsCore.groups(state.lines,CATALOG)[i],rule=g?.rules[j];if(!rule)return;const c=MaterialSuggestionsCore.options(rule,CATALOG).find(c=>c.id===$(`suggest-${i}-${j}`).value);if(!c)return;if(MaterialSuggestionsCore.exists(state.lines,c,g.group,g.scope)){toast('Эта позиция уже есть в данной группе и области учёта');return;}const l=lineFrom(rule.custom?undefined:c);Object.assign(l,{catalogId:c.id,name:c.name,kind:c.kind,unit:c.unit,price:c.price??null,group:g.group,scope:g.scope,qty:null,confirmed:false});if(rule.custom)l.source='Ручная ставка: отдельная ставка торцовки в справочнике отсутствует';state.lines.push(l);persist();render();editLine(l.id);}
function installationReminderHTML(){const notice=MaterialSuggestionsCore.installationNotice(state);return `<div class="note info" id="installation-reminder"><b>Монтажная спецификация</b><p>${esc(notice||'Монтаж проверен: '+(MaterialSuggestionsCore.installationRequired(state)?'входит в заказ.':'не входит в заказ.'))}</p>${page===19?'':'<button onclick="go(19)">Открыть раздел монтажа</button>'}</div>`;}
function renderInstallation(){const spec=state.installationSpec||{reviewed:false,notes:''},included=MaterialSuggestionsCore.installationRequired(state),r=CostEngine.calculate(state),lines=MaterialSuggestionsCore.installationLines({...state,lines:r.rows});$('app').innerHTML=title('Состав заказа','Монтаж и спецификация','Укажите работы, крепёж и расходные материалы для монтажа. Объёмы по умолчанию относятся ко всей партии.',spec.reviewed?'Проверено':'Нужно заполнить')+`<section class="card"><div class="field"><label for="installation-included">Монтаж в составе заказа</label><select id="installation-included" onchange="installationSetting('included',this.value==='yes')"><option value="no" ${!included?'selected':''}>Не входит в заказ</option><option value="yes" ${included?'selected':''}>Входит в заказ</option></select></div><div class="field"><label for="installation-notes">Условия и состав монтажа</label><textarea id="installation-notes" rows="4" oninput="installationSetting('notes',this.value)" placeholder="Место установки, основание, способ крепления, доступ техники, состав бригады…">${esc(spec.notes)}</textarea></div><label class="checkrow"><input id="installation-reviewed" type="checkbox" ${spec.reviewed?'checked':''} onchange="installationSetting('reviewed',this.checked)">Проверены необходимость монтажа, состав и условия</label><p class="small">Крепёж, анкеры, химические составы, технику и трудозатраты добавляйте по проекту. Если монтаж исключён, оставшиеся монтажные позиции продолжат учитываться — перенесите или удалите их явно.</p></section><section class="card"><h2>Монтажная спецификация</h2><div class="mini-actions"><button onclick="picker('work')">Добавить работу из справочника</button><button onclick="picker('material')">Добавить материал из справочника</button><button onclick="installationManual('work')">Своя работа</button><button onclick="installationManual('material')">Свой материал</button></div><p class="small">Позиции входят в общую калькуляцию один раз. Ставки, область учёта и закупочная кратность редактируются в позиции.</p><div class="tablewrap"><table><thead><tr><th>Позиция</th><th>Объём</th><th>Область учёта</th><th>Ставка</th><th></th></tr></thead><tbody>${lines.map(l=>`<tr><td>${esc(l.name)||'Новая позиция'}<span class="source">${l.kind==='work'?'Работа':'Материал'}</span></td><td>${dec(l.qty)} ${esc(MaterialCore.unitLabel(l.unit))}</td><td>${l.scope==='batch'?'Вся партия':'На изделие'}</td><td>${money(l.price)}</td><td><button onclick="editLine('${esc(l.id)}')">Изменить</button></td></tr>`).join('')||'<tr><td colspan="5">Спецификация пока пустая.</td></tr>'}</tbody></table></div></section>${installationReminderHTML()}<div class="mini-actions"><button onclick="go(2)">К производственным работам</button><button onclick="go(4)">К результату</button></div>`;}
function installationSetting(k,v){const old=state.installationSpec||{notes:'',reviewed:false};state.installationSpec={...old,[k]:v};if(k==='included'){delete state.installationSpec.included;state.requiredServices={...(state.requiredServices||{installation:MaterialSuggestionsCore.installationRequired(state),delivery:/Комплексный/.test(state.scope),design:/Проектирование|Комплексный/.test(state.scope)}),installation:v};state.installationSpec.reviewed=false;}if(k==='notes')state.installationSpec.reviewed=false;persist();if(k==='notes'){if($('installation-reviewed'))$('installation-reviewed').checked=false;const tag=$('app').querySelector?.('.page-title .tag');if(tag)tag.textContent='Нужно заполнить';if($('installation-reminder'))$('installation-reminder').outerHTML=installationReminderHTML();return;}render();}
function markInstallation(l){if(l.kind==='material')l.installation=true;l.group='Монтаж';l.scope='batch';if(l.kind==='work')l.costCategory='installation';if(state.lines.includes(l))state.installationSpec={...(state.installationSpec||{notes:''}),reviewed:false};}
function installationManual(kind){const l=lineFrom();Object.assign(l,{kind,name:kind==='work'?'Монтажная работа':'Монтажный материал',unit:kind==='work'?'н/ч':'шт.'});markInstallation(l);pendingNewLine=l;editLine(l.id);}
(function(){
 const originalRender=render;render=function(){originalRender();if([1,2].includes(page))$('app').insertAdjacentHTML('beforeend',typeof materialRouteRecommendationsHTML==='function'?materialRouteRecommendationsHTML():materialSuggestionsHTML());if([0,2].includes(page))$('app').insertAdjacentHTML('beforeend',installationReminderHTML());};
 const originalResult=renderResult;renderResult=function(){originalResult();if(mode==='internal')$('app').insertAdjacentHTML('beforeend',installationReminderHTML());};
 const originalAdd=addCatalog;addCatalog=function(id){if(page!==19)return originalAdd(id);const c=CATALOG.find(c=>c.id===id);if(!c)return;if(MaterialSuggestionsCore.installationLines(state).some(l=>l.catalogId===id)){toast('Такая позиция уже есть в монтажной спецификации');return;}const l=lineFrom(c);markInstallation(l);pendingNewLine=l;$('modal').close();editLine(l.id);};
 const originalService=serviceSetting;serviceSetting=function(k,v){if(k==='installation'&&state.installationSpec)state.installationSpec.reviewed=false;return originalService(k,v);};
 const originalEdit=editLine;editLine=function(id){originalEdit(id);const l=editableLine(id);if(l?.kind==='material'&&$('lineForm'))$('lineForm').insertAdjacentHTML('afterbegin',`<label class="checkrow"><input id="line-installation" type="checkbox" ${l.installation?'checked':''}>Материал для монтажной спецификации</label>`);};
 const originalCommit=commitLine;commitLine=function(e,id){const flag=$('line-installation'),included=flag?.checked,result=originalCommit(e,id);if(result===false||$('modal').open)return result;const l=editableLine(id);if(flag&&l?.kind==='material'){l.installation=!!included;persist();render();}return result;};
 const originalPersist=persist;persist=function(){if(state.installationSpec?.reviewed&&state.installationSpec.contentSignature!==installationContentSignature(state))state.installationSpec.reviewed=false;originalPersist();};
 const originalSetting=installationSetting;installationSetting=function(k,v){if(k==='reviewed'&&v){if(MaterialSuggestionsCore.installationRequired(state)&&(!state.installationSpec?.notes.trim()||!MaterialSuggestionsCore.installationLines(state).some(l=>l.kind==='work'))){toast('Заполните условия и добавьте монтажные работы перед проверкой');render();return;}state.installationSpec={...(state.installationSpec||{notes:''}),reviewed:true,contentSignature:installationContentSignature(state)};persist();render();return;}return originalSetting(k,v);};
})();
function installationContentSignature(c){const effective=typeof ProcessGraphCore!=='undefined'?ProcessGraphCore.resolve(c).state:c;const lines=MaterialSuggestionsCore.installationLines(effective).map(l=>({name:l.name,unit:l.unit,qty:l.qty,price:l.price,reserve:l.reserve,pack:l.pack,scope:l.scope,allocation:l.allocation,group:l.group,kind:l.kind,confirmed:!!l.confirmed,deliveryIncluded:!!l.deliveryIncluded,mass:Number.isFinite(l.mass)?l.mass:null,costCategory:ReviewCore.category(l),pricingMode:l.pricingMode||'cost',normNote:l.normNote||'',installation:!!l.installation,operation:l.operation||null}));return ReviewCore.signature({qty:c.qty,required:MaterialSuggestionsCore.installationRequired(c),notes:c.installationSpec?.notes||'',lines});}
render();
